use kernel::{Config,Engine,Input,output::verify_record,value::read_json};
use serde_json::json;
use std::path::PathBuf;
fn main() {
    let args:Vec<_>=std::env::args().collect();
    let input_path=PathBuf::from(&args[1]);let record_path=PathBuf::from(&args[2]);let config_path=PathBuf::from(&args[3]);
    let config=Config::parse(read_json(&config_path).unwrap()).unwrap();
    let input=Input::load(&input_path,&config,false);
    if let Err(e)=input {println!("{}",json!({"input_loaded":false,"error":e.to_string()}));return;}
    let seed=Engine::new(input.as_ref().unwrap().clone());
    let result=verify_record(&read_json(&record_path).unwrap(),input.unwrap(),&config,&config_path);
    println!("{}",json!({"input_loaded":true,"engine_created":seed.is_ok(),"engine_error":seed.err().map(|e|e.to_string()),"verify_accepted":result.is_ok(),"verify_error":result.err().map(|e|e.to_string())}));
}
